import React, { useState } from 'react';
import { 
  Button, 
  Drawer, 
  Space, 
  Typography, 
  Avatar,
  Divider,
  Badge
} from 'antd';
import { 
  MenuOutlined, 
  HomeOutlined, 
  FileTextOutlined, 
  SettingOutlined,
  MessageOutlined,
  RobotOutlined,
  CreditCardOutlined,
  UserOutlined,
  CloseOutlined,
  CrownOutlined,
  QuestionCircleOutlined
} from '@ant-design/icons';
import { useNavigate, useLocation } from 'react-router-dom';
import { APP_VERSION_LABEL, FOOTER_VERSION_LINE } from '../config/version';

const { Title, Text } = Typography;

interface ModernHeaderProps {
  activePersonality?: string;
  embedded?: boolean; // если true — рендерим без собственного контейнера topbar
}

const ModernHeader: React.FC<ModernHeaderProps> = ({ activePersonality, embedded = false }) => {
  const [drawerVisible, setDrawerVisible] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  
  // Определяем контекст приложения (Telegram или тестовая среда)
  const isTelegramMiniApp = typeof window !== 'undefined' && (
    !!((window as any).Telegram?.WebApp) ||
    !!window.location.hostname.includes('t.me') ||
    !!window.location.hostname.includes('telegram.org') ||
    !!window.location.hostname.endsWith('soulpulse.art') ||
    !!document.body.classList.contains('telegram-mini-app')
  );

  // Дебаг информация для отладки
  React.useEffect(() => {
    console.log('🔍 ModernHeader Telegram detection:');
    console.log('- hostname:', window.location.hostname);
    console.log('- isTelegramMiniApp:', isTelegramMiniApp);
    console.log('- body classes:', document.body.className);
    console.log('- Telegram WebApp:', !!(window as any).Telegram?.WebApp);
    console.log('- Title color will be:', isTelegramMiniApp ? 'var(--sp-text-primary)' : 'var(--text-primary)');
    console.log('- Navigation text color will be:', isTelegramMiniApp ? 'var(--sp-text-secondary)' : 'var(--text-secondary)');
  }, [isTelegramMiniApp]);

  const showDrawer = () => {
    setDrawerVisible(true);
  };

  const onClose = () => {
    setDrawerVisible(false);
  };

  const getActivePageTitle = () => {
    const path = location.pathname;
    switch (path) {
      case '/':
        return 'Главная';
      case '/prompts':
        return 'Личности';
      case '/settings':
        return 'Настройки';
      case '/chat':
        return 'Чат в приложении';
      case '/llm-settings':
        return 'Настройки ИИ';
      case '/architect':
        return 'Панель Архитектора';
      case '/soul/goals':
        return 'Цели Соул';
      case '/soul/logs':
        return 'Соул · Логи';
      case '/soul/activities-goals':
        return 'Интеграция Активностей';
      case '/payments':
        return 'Платежи';
      case '/help':
        return 'Справка';
      case '/chat-management':
        return 'Управление чатом';

      default:
        return 'SoulPulse';
    }
  };

  const getActivePageIcon = () => {
    const path = location.pathname;
    switch (path) {
      case '/':
        return <HomeOutlined />;
      case '/prompts':
        return <FileTextOutlined />;
      case '/settings':
        return <SettingOutlined />;
      case '/chat':
        return <MessageOutlined />;
      case '/llm-settings':
        return <RobotOutlined />;
      case '/architect':
        return <SettingOutlined />;
      case '/soul/goals':
        return <RobotOutlined />;
      case '/soul/logs':
        return <FileTextOutlined />;
      case '/payments':
        return <CreditCardOutlined />;
      case '/help':
        return <QuestionCircleOutlined />;
      case '/chat-management':
        return <SettingOutlined />;

      default:
        return <HomeOutlined />;
    }
  };

  const navigationItems = [
    { path: '/', icon: <HomeOutlined />, label: 'Главная' },
    { path: '/webauth', icon: <UserOutlined />, label: 'WebAuth' },
    { path: '/prompts', icon: <FileTextOutlined />, label: 'Личности' },
    { path: '/settings', icon: <SettingOutlined />, label: 'Настройки' },
    { path: '/chat', icon: <MessageOutlined />, label: 'Чат в приложении' },
    { path: '/llm-settings', icon: <RobotOutlined />, label: 'Настройки ИИ' },
    { path: '/architect', icon: <SettingOutlined />, label: 'Панель Архитектора' },
    { path: '/architect/monitoring', icon: <SettingOutlined />, label: 'Monitoring' },
    { path: '/soul/goals', icon: <RobotOutlined />, label: 'Цели Соул' },
    { path: '/soul/logs', icon: <FileTextOutlined />, label: 'Логи' },
    { path: '/soul/activities-goals', icon: <CrownOutlined />, label: 'Интеграция Активностей' },
    { path: '/admin/ui/forms', icon: <SettingOutlined />, label: 'Реестр форм' },
    { path: '/all-pages', icon: <FileTextOutlined />, label: 'Все страницы' },
    { path: '/payments', icon: <CreditCardOutlined />, label: 'Платежи' },
    { path: '/help', icon: <QuestionCircleOutlined />, label: 'Справка' },
    { path: '/chat-management', icon: <SettingOutlined />, label: 'Управление чатом' },
    { path: '/keywords', icon: <FileTextOutlined />, label: 'Ключевые слова' },
    { path: '/dates-reminders', icon: <FileTextOutlined />, label: 'Даты и напоминания' },

  ];

  const handleLogout = () => {
    try {
      sessionStorage.removeItem('token');
      sessionStorage.removeItem('telegram_user');
      sessionStorage.removeItem('tg_id');
      localStorage.removeItem('token');
      try { navigate('/webauth', { replace: true }); } catch { 
        try { window.location.hash = '#/webauth'; } catch { window.location.replace('/#\/webauth'); }
      }
    } catch (e) {
      try { navigate('/webauth', { replace: true }); } catch { 
        try { window.location.hash = '#/webauth'; } catch { window.location.replace('/#\/webauth'); }
      }
    }
  };

  const handleNavigation = (path: string) => {
    navigate(path);
    onClose();
  };

  const isActivePage = (path: string) => {
    return location.pathname === path;
  };

  const routeToStartParam = (path: string): string => {
    switch (path) {
      case '/': return 'home';
      case '/chat': return 'chat';
      case '/prompts': return 'prompts';
      case '/realtime-voice': return 'realtime';
      case '/all-pages': return 'all';
      case '/settings': return 'settings';
      case '/help': return 'help';
      case '/payments': return 'payments';
      case '/keywords': return 'keywords';
      case '/dates-reminders': return 'reminders';
      default: return 'home';
    }
  };

  const openInTelegram = () => {
    try {
      const sp = routeToStartParam(location.pathname);
      const tgLink = 'tg://resolve?domain=soulpulse_mini_bot&startapp=' + encodeURIComponent(sp);
      const webLink = 'https://t.me/soulpulse_mini_bot';
      try { window.location.href = tgLink; } catch {}
      setTimeout(() => { try { window.open(webLink, '_blank'); } catch {} }, 120);
    } catch {}
  };

  const HeaderInner = (
    <>
      {/* Кнопка меню слева */}
      <Button
        type="text"
        shape="circle"
        size="large"
        aria-label="Открыть меню"
        icon={<MenuOutlined style={{ fontSize: 20, color: 'var(--sp-color-primary)' }} />}
        onClick={showDrawer}
        style={{ 
          color: 'var(--sp-color-primary)',
          flexShrink: 0,
          padding: 6,
          background: 'var(--sp-bg-secondary)',
          border: '1px solid var(--sp-border-primary)',
          boxShadow: '0 2px 8px rgba(0,0,0,0.12)',
          zIndex: 1100
        }}
        className="menu-toggle-btn"
      />
      {(() => { try { console.log('[ModernHeader] menu button rendered:', !!document.querySelector('.menu-toggle-btn')); } catch {} return null; })()}
      {/* Брендинг */}
      <div className="brand-section" style={{ 
        display: 'flex', 
        alignItems: 'center', 
        gap: 'var(--sp-spacing-sm)',
        flex: 1,
        overflow: 'hidden' 
      }}>
        <RobotOutlined style={{ 
          fontSize: 'var(--sp-font-size-lg)', 
          color: 'var(--sp-color-primary)',
          filter: 'drop-shadow(0 2px 6px rgba(107,123,209,0.35))',
          flexShrink: 0
        }} />
        <div style={{ overflow: 'hidden' }}>
          <Text style={{ 
            color: 'var(--sp-text-primary)', 
            fontSize: 'var(--sp-font-size-base)', 
            fontWeight: '600',
            display: 'block',
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis'
          }}>
            Интеллектуальный чат-бот
          </Text>
        </div>
      </div>
    </>
  );

  return (
    <>
      {embedded ? (
        <div style={{display:'flex', alignItems:'center', gap:'var(--sp-spacing-md)'}}>
          {HeaderInner}
        </div>
      ) : (
        <div className="app-topbar sp-edge-highlight" style={{
          background: 'var(--sp-bg-card)',
          backdropFilter: 'blur(12px)',
          WebkitBackdropFilter: 'blur(12px)',
          padding: 'var(--sp-spacing-xs) var(--sp-spacing-md)',
          borderBottom: '1px solid var(--sp-border-primary)',
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--sp-spacing-md)',
          position: 'sticky',
          top: 0,
          zIndex: 1000
        }}>
          {HeaderInner}
        </div>
      )}

      {/* Боковое меню */}
      <Drawer
        title={
          <div className="brand-section">
            <Title level={4} style={{ 
              margin: 0, 
              color: (isTelegramMiniApp || window.location.hostname.endsWith('soulpulse.art')) ? 'var(--sp-text-primary)' : 'var(--text-primary)',
              fontWeight: '600'
            }}>
              SoulPulse
            </Title>
            <Text style={{ 
              color: (isTelegramMiniApp || window.location.hostname.endsWith('soulpulse.art')) ? 'rgba(255, 255, 255, 0.9)' : 'var(--text-secondary)',
              fontSize: '14px'
            }}>
              Навигация
            </Text>
          </div>
        }
        placement="right"
        onClose={onClose}
        open={drawerVisible}
        styles={{
          body: { padding: '16px', background: 'var(--bg-secondary)' },
          header: { background: 'var(--bg-secondary)', borderBottom: '1px solid var(--border-color)' }
        }}
      >
        <div className="menu-content">
          {/* Текущая страница */}
          <div className="current-page" style={{
            background: 'var(--bg-card)',
            padding: '16px',
            borderRadius: '8px',
            marginBottom: '24px',
            border: '1px solid var(--border-color)'
          }}>
            <Space>
              {getActivePageIcon()}
              <div>
                <Text strong style={{ 
                  color: (isTelegramMiniApp || window.location.hostname.endsWith('soulpulse.art')) ? 'var(--sp-text-primary)' : 'var(--text-primary)',
                  fontWeight: '600'
                }}>
                  {getActivePageTitle()}
                </Text>
                <br />
                <Text style={{ 
                  fontSize: '12px',
                  color: (isTelegramMiniApp || window.location.hostname.endsWith('soulpulse.art')) ? 'rgba(255, 255, 255, 0.8)' : 'var(--text-secondary)',
                  opacity: 1
                }}>
                  Текущая страница
                </Text>
              </div>
            </Space>
          </div>

          {/* Навигационные элементы */}
          <div className="navigation-items">
            {navigationItems.map((item) => (
              <div
                key={item.path}
                className={`nav-item ${isActivePage(item.path) ? 'active' : ''}`}
                onClick={() => handleNavigation(item.path)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  padding: '12px 16px',
                  marginBottom: '8px',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  transition: 'all 0.2s ease',
                  background: isActivePage(item.path) 
                    ? 'var(--primary-color)' 
                    : (isTelegramMiniApp ? 'rgba(0, 0, 0, 0.3)' : 'transparent'),
                  color: isActivePage(item.path) ? 'var(--sp-text-primary)' : (isTelegramMiniApp ? 'var(--sp-text-primary)' : 'var(--text-primary)'),
                  border: isActivePage(item.path) ? 'none' : '1px solid var(--border-color)'
                }}
              >
                <span className="nav-icon" style={{ marginRight: '12px', fontSize: '18px' }}>
                  {item.icon}
                </span>
                <span className="nav-text">{item.label}</span>
              </div>
            ))}
          </div>

          <Divider style={{ borderColor: 'var(--border-color)' }} />

          {/* Быстрая ссылка: открыть текущую страницу в Telegram */}
          <div style={{ marginBottom: 16 }}>
            <Button type="primary" block onClick={openInTelegram}>
              Открыть в Telegram
            </Button>
          </div>

          {/* Активная личность */}
          {activePersonality && (
            <div className="active-personality" style={{
              background: 'var(--bg-card)',
              padding: '16px',
              borderRadius: '8px',
              border: '1px solid var(--border-color)'
            }}>
              <Space>
                <CrownOutlined style={{ 
                    color: (isTelegramMiniApp || window.location.hostname.endsWith('soulpulse.art')) ? 'var(--sp-color-warning)' : 'var(--accent-color)'
                }} />
                <div>
                  <Text strong style={{ 
                    color: (isTelegramMiniApp || window.location.hostname.endsWith('soulpulse.art')) ? 'var(--sp-text-primary)' : 'var(--text-primary)',
                    fontWeight: '600'
                  }}>
                    Активная личность
                  </Text>
                  <br />
                  <Text style={{ 
                    color: (isTelegramMiniApp || window.location.hostname.endsWith('soulpulse.art')) ? 'var(--sp-text-secondary)' : 'var(--text-secondary)',
                    opacity: 1
                  }}>
                    {activePersonality}
                  </Text>
                </div>
              </Space>
            </div>
          )}

          {/* Футер меню */}
          <div className="menu-footer" style={{
            marginTop: 'auto',
            paddingTop: '16px',
            borderTop: '1px solid var(--border-color)',
            textAlign: 'center'
          }}>
            <Space direction="vertical" style={{ width: '100%' }}>
              <Button onClick={handleLogout} danger block>
                Выйти
              </Button>
              <Text type="secondary" style={{ fontSize: '12px' }}>
                {APP_VERSION_LABEL}
              </Text>
              <Text type="secondary" style={{ fontSize: '10px', opacity: 0.8 }}>
                {FOOTER_VERSION_LINE}
              </Text>
            </Space>
          </div>
        </div>
      </Drawer>
    </>
  );
};

export default ModernHeader;
